insert into public.publishers (exhibitor_no, booth_number, original_booth_number, name, name_en, country_ko, country_en, is_special, categories, introduction, homepage, instagram, sort_order) values
  (293, 'B400', 'B417', '0.1', '0.1', null, null, true, array['예술']::text[], '2013년부터 ‘0.1’이라는 이름으로 언니 0과 동생 1이 함께 그립니다. 그리고 그 그림을 담는 틀과 형식도 만듭니다. 유년 시절 보았던 애니메이션이나 그림책에서 영감을 받아 아이들을 주인공으로 한 이야기들을 그려나가고 있습니다. 실크스크린, 재봉, 핸드 바인딩 등 수작업을 주로 이용해 아트북과 여러 가지 제품을 만들고 있습니다. 2019년부터는 디자인 스튜디오 디오브젝트와 함께 ‘Add to Cart’라는 이름으로 오브제, 전통, 수집 등의 키워드를 다양한 형태의 책으로 표현하는 프로젝트 그룹도 진행하고 있습니다.', null, 'https://www.instagram.com/1choo/', 293),
  (294, 'B400', 'B418', '검정프레스', 'geomjung press', null, null, true, array['예술','기타(여행','음식','사진','디자인)']::text[], '미술, 건축, 디자인, 사진, 패션, 음식 등 감각을 기반으로, 묵묵히 자신의 일을 이어가는 사람들의 이야기와 그 콘텐츠를 (종이)책으로 출판합니다. (종이)책의 본질은 하얀 종이 위에 인쇄된 검정 잉크라는 믿음에서 시작해, (종이)책이 지닌 물성을 탐구하고 읽기 위한 매체로서의 한계에 질문합니다. 이러한 과정 속에서 다채롭고 생경한 경험을 전달하는 (종이)책을 실험하고 제안합니다. 우리는 (종이)책에서만 경험할 수 있는 감각과 기분을 좋아합니다. 그리고 그것을 잘하기 위해 언제나 집중합니다.', null, 'https://www.instagram.com/geomjungpress/', 294),
  (295, 'B400', 'B419', '써니라운드', 'SUNNYROUND', null, null, true, array['예술','기타(쿡북)']::text[], '써니라운드(SUNNYROUND)는 푸드스타일리스트가 운영하는 크리에이티브 푸드 콘텐츠 스튜디오입니다. 상업적인 푸드 콘텐츠를 위한 스타일링 작업과 함께, ‘써니라운드’라는 이름처럼 밝고 따뜻한 감정을 담은 요리책을 제작하고 있습니다. 개성 있는 내용의 독립출판 요리책을 시작으로, 요리와 시각 예술이 만나는 지점을 탐구하며 다양한 형식의 책을 만들고 있습니다. 현재는 아트북과 쿡북의 경계를 연구하며, 요리책이 하나의 창작물로 기능할 수 있는 가능성을 실험하는 출판 작업을 이어가고 있습니다.', 'https://www.sunnyround.co.kr/cookbook', 'https://www.instagram.com/sunnyround_official/', 295),
  (296, 'B400', 'B420', '픽션들', 'fictiondle', null, null, true, array['예술','문학']::text[], '픽션들은 2020년 음악가 이아립이 보르헤스의 소설 『픽션들』에 영감을 받아 만든 출판사입니다. 때로는 허구가 사실보다 진실에 더 가까운 것을 목도하면서 ‘픽션과 픽션에 가까운 것’을 만들고자 설립했습니다. AI의 결함을 담은 SF소설을 시작으로 한 작가의 다양한 장르를 담은 ‘1인들’ 시리즈와 예술가들과의 협업을 통한 앤솔로지와 악보집, 송북과 문학 포스터를 기획 제작합니다. 문학이라는 테두리 안에서 경계를 넘나드는 다양한 형태의 텍스트를 꿈꿉니다. 좋은 책은 좋은 질문을 하게 만드는 것이라 생각합니다. 독서를 통해 인생의 질문들을 찾게 되기를 기대합니다.', null, 'https://www.instagram.com/fictiondle/', 296),
  (297, 'B400', 'B421', '남섬책방', 'Namseom Books', null, null, true, array['예술','아동','기타(만화 에세이)']::text[], '작가 남섬이 운영하는 1인 출판사입니다. 남쪽 섬에서의 한때처럼 온기가 있어 여운이 남고, 엉뚱함이 있어 쉼이 되는 책을 지향합니다. 느릿하지만 단단한 손길로 빚어낸 남섬책방의 그림책과 만화책을 만나보세요. 이곳, 남섬에서.', null, 'https://www.instagram.com/namsermbook/', 297),
  (298, 'B400', 'B422', '시네필 책방 코프키노', 'KopfKino', null, null, true, array['예술']::text[], '시네필 책방 코프키노는 중랑구에 위치한 독립 서점 겸 독립 출판사입니다. ''코프키노''는 독일어로 ''머리(코프)''와 ''영화관(키노)''의 합성어로, 공상을 많이 하는 사람이라는 뜻입니다. 코프키노는 ''더 많은 생각, 더 많은 영화''를 표어로 시네필을 위한 도서 출판 및 다양한 활동을 기획하고 있습니다. 코프키노는 2025년 1월에 개업했으며 2025년 [마티아스 피녜이로: 방랑하는 영화, 모험하는 영화]를 출간했습니다. 2025년 3월 [사탄탱고: 벨라 타르에 들어가기 앞서]를 출간, 2025년 6월 [아트 호러: 아리 애스터와 로버트 에거스의 영화]를 출간하며 예술영화관 ''아트하우스 모모''와 함께 ''로버트 에거스 미니 기획전''을 진행했습니다. 2026년 2월 [켈리 라이카트: 어떤 여자와 어떤 영화들]을 출간할 예정이며 5월 [태풍클럽 각본집], [숀벤라이더/바람꽃 각본집]을 출간할 예정입니다.', null, 'https://instagram.com/books_by_kopfkino/', 298),
  (299, 'B400', 'B423', '요호이', 'yohoi', null, null, true, array['예술','문학']::text[], '“행복은 결국 내 안에서 시작된다(Happiness is an inside job)”는 철학을 바탕으로, 잉크펜과 수채화 드로잉을 하며 기쁨과 유머를 담은 책을 만들고 있습니다. 짧은 한 문장과 단순한 그림 하나가 우리가 세상을 바라보는 시선을 바꿀 수 있다고 믿습니다. 서울, 런던, 타이베이, 상하이, 선전 등 여러 도시에서 열리는 국제 아트북 페어에 꾸준히 참여하며, 출판 활동의 영역을 넓히고 국경을 넘어 독자들과 연결되고자 노력하고 있습니다.', null, 'https://www.instagram.com/kimjourneydiary/', 299),
  (300, 'B400', 'B424', '스튜디오604', 'STUDIO604', null, null, true, array['예술','문학','아동']::text[], '스튜디오604는 일러스트레이터 유꽁사가 운영하는 1인 브랜드입니다. 글과 그림, 요리 등 일상의 다양한 요소를 창작의 소재로 삼아, 이를 글과 이미지, 혹은 물성이 있는 작업물로 세상에 선보이고 있습니다. 독립출판사로서 에세이 『혼자 보는 일기』와 만화 『너구리 탐정 사무소』를 출간했으며, 이를 바탕으로 한 캐릭터와 스토리텔링 작업을 통해 다양한 브랜드와 협업하고 전시 활동을 이어가고 있습니다. 세미콜론과 함께 요리 에세이 『눈앞이 캄캄해도 나아가기를 멈추지 않고』를 출간하며, 독립출판을 넘어 다양한 영역으로 창작 활동을 확장하고 있습니다.', null, 'https://www.instagram.com/604.jpg/', 300),
  (301, 'B400', 'B425', '돛과닻', 'Sail and Anchor', null, null, true, array['예술','문학']::text[], '돛과닻은 미술작가 김영글이 2019년 문을 연 독립출판 스튜디오입니다. 장르의 경계를 항해하며 멀리 그리고 깊이 이동하는 책을 만듭니다.', 'http://www.sailandanchor.net', 'https://instagram.com/sailandanchor/', 301),
  (302, 'B400', 'B426', '스크립토', 'Scripto', null, null, true, array['종교','예술','언어','역사']::text[], '스크립토는 문자 예술 도서를 소개하는 출판사로 시작했습니다. 이제는 지평을 넓혀 보다 다양한 문화와 예술 분야를 아우르는 출판사로 나아가고 있습니다. 스크립토는 사람들의 시선에서 비켜나 있던 대상을 새롭게 조명하며, 그 세계를 독자 앞에 다시 펼쳐 보이는 작업을 이어왔습니다. 이제는 문화와 예술 전반으로 관심을 확장하여 자신만의 세계를 독립적이고 굳건하게 표현하며 살아가는 존재들을 소개하고자 합니다. 그 존재가 드러내는 고유한 세계가 많은 이들에게 다양한 감각을 일깨우고, 더 깊은 사유로 이어지기를 바랍니다. 책 제작 시간이 다소 걸리더라도 내용에 가장 어울리는 책 형태와 종이, 디자인과 제본 방식 등 모든 공정에 심혈을 기울입니다. 궁극적으로는 독자가 오래도록 소장하고 싶은 책을 만들고자 합니다.', 'http://www.scripto.kr', 'https://www.instagram.com/scripto_publisher/', 302),
  (303, 'B400', 'B427', '타바코북스', 'TABACOBOOKS', null, null, true, array['예술']::text[], '그림을 그리고 1인 출판사 타바코북스를 운영하고 있는 기탁입니다. 오래 간직하고 싶은 그림들로 책을 만들기 위해 꾸준히 작업을 이어가고 있습니다. 느린 호흡의 영화처럼, 느슨하지만 그 안에 담긴 아름다움을 추구합니다. 2017년부터 매년 다른 주제로 아트북을 만들어 왔으며, 지금까지 12권의 책과 진을 선보였습니다. 기획, 그림, 편집, 디자인, 제작 전 과정을 혼자 진행하며, 각 책마다 형식과 구성에 변화를 두는 방식을 지속해 왔습니다. 독립출판물을 베이스로 활동하고 있으며 2025년에는 서울의 아트북페어 언리밋티드 에디션을 시작으로, 대만 타이베이 아트북페어와 일본 도쿄 아트북페어에 참가해 작업을 소개했고, 현장에서 좋은 반응을 얻었습니다. 타바코북스는 개인의 감각과 속도로 운영되는 독립출판사입니다. 무엇을, 어떻게 만들 것인가에 제약이 없는 환경에서 매년 새로운 시도를 이어가며, 이 작업의 흐름을 오래 유지하고자 합니다. 이번 서울국제도서전 역시 이러한 작업을 직접 소개하고, 독립출판의 맥락 안에서 더 많은 독자와 연결되기 위해 참여하고자 합니다. 잘부탁드립니다.', 'https://tabacobooks.kr/tabacobooks_archive', 'https://www.instagram.com/toclamp/', 303),
  (304, 'B400', 'B428', '머쉬룸', 'mushRoom', null, null, true, array['예술','문학']::text[], '안녕하세요, 1인 출판사 ‘mushRoom’을 운영하는 디자이너이자 일러스트레이터 김주희입니다. 식물의 독특하고 예측 불가능한 속성에서 영감을 받아 가상의 캐릭터를 만들고, 이들의 이야기를 동화로 엮어 아트북과 굿즈로 제작하고 있습니다. 부드럽거나 가끔은 예민할지라도, 저마다가 가진 다양한 모습과 가치관을 온전히 사랑하는 방법에 대해 이야기합니다. 식물을 메인 주제로 삼아 다양한 세계관을 만들어내며, 최근에는 이를 확장하여 실제로 식물을 이용해 잉크를 만드는 등 더 넓은 범위로 작업을 이어가고 있습니다.', null, 'https://www.instagram.com/mushroom_chaeri/', 304),
  (305, 'B400', 'B429', '소환사', 'Sohwansa', null, null, true, array['예술','문학']::text[], '소환사는 예술가의 글, 예술에 대한 글을 출판하는 1인 출판사입니다. 예술을 마주치는 방식들에 대한 호기심을 바탕으로 책을 기획합니다. 텍스트가 지닌 고유한 무게와 질감에 집중하며, 책의 내용과 형식 사이의 관계를 끊임없이 탐색합니다. 예술의 언어에 고유한 물성을 부여하고자, 원고의 성질과 어울리는 파트너와 협업하여, 원고가 도달할 수 있는 가장 적절한 모양을 찾아갑니다.', 'http://www.sohwansa.kr', null, 305),
  (306, 'B400', 'B430', '마그네틱 파이브', 'MAGNETIC 5', null, null, true, array['예술']::text[], 'MAGNETIC 5는 서울에 위치한 리소 인쇄 및 출판 스튜디오입니다. 사진, 인쇄, 예술 교육 등 다양한 분야에서 활동하는 박 린과 김병덕이 운영하고 있습니다. 저희의 탐구는 우리 주변에 숨겨진 이야기들을 발견하는 것에서 시작됩니다. 그리고 그 이야기들을 진(zine)과 아트북으로 만들어냅니다.', null, null, 306),
  (307, 'B400', 'B431', '하호하호', 'hahahaha', null, null, true, array['예술']::text[], '흑백 펜화의 일러스트레이션 위주로 작업하며, 글을 쓰고 독립출판물을 만듭니다. 9년 동안 작업 활동을 해 오며 16종 이상의 다양한 장르의 책을 만들었습니다. 외부 세계와 내면 세계가 만나는 지점에 대해 고민하고 묘사합니다. 돌과 새, 꽃과 나무, 그리고 사람들이 가진 개인적인 감정 등, 우리 주위에 있지만 자세히 들여다보지 않으면 눈치채기 어려운 것들을 섬세한 흑백의 펜화로 묘사해 오랫동안 시선이 머무르게끔 합니다.', null, 'https://www.instagram.com/hahohaho00/', 307),
  (308, 'B400', 'B432', '1도씨와 온도들', '1docci', null, null, true, array['예술']::text[], '2014년 공연예술전문출판사로 시작한 1도씨와 온도들은 ‘극장과 공연예술 주위의 재미있는 일’을 하는 곳입니다. 극장과 사람, 공연과 세계 사이 재미있는 일, 필요한 일, 없었던 일들을 발견하고 만듭니다. 공연의 행위와 과정이 사람에게 좋은 영향을 미친다는 생각을 전제로 ‘인간술로서의 공연예술''을 지향합니다. 클래스, 출판, 읽을거리, 커뮤니티를 제공합니다. 또한 동시대 문화예술을 중심으로 아카이빙, 리서치, 기획, 프로젝트를 도모하고 함께합니다. 1도씨와 온도들은 새로운 관점과 세계를 만드는 극장, 학교, 출판사, 커뮤니티가 되고자 합니다.', 'http://www.1docci.com', null, 308),
  (309, 'B400', 'B433', '후루룩', 'Hooloolook', null, null, true, array['문학']::text[], '‘후루룩’하고 넘어가는 국수처럼 미끄럽게 넘길 수 있는 재밌는 글을, 한 권의 책을 읽고 배부름과 즐거움이 두둑하게 채워질 수 있는 이야기를, 무엇보다 맛있는 책을 만들고 있습니다.', null, 'https://www.instagram.com/1jh.wonderland/', 309),
  (310, 'B400', 'B434', '유일무이(누구나)', 'NUGUNA', null, null, true, array['예술','문학','기타(그림에세이)']::text[], '글과 그림일기로 책을 만드는 작가이자 디자이너이자 대표인 ‘누구나’의 작업물로 이루어진 1인 출판사 ‘유일무이’입니다. 세상에 하나뿐인, 유일무이한 누군가의 이야기가 결국 누구나 공감하고 위안을 주는 힘이 될 때가 있습니다. 각자가 가진 이야기의 무게와 힘을 믿으며 우리와 가까운 이야기를 모아 전달하고 있습니다. 그로 인해 독자에게 개개인이 얼마나 특별하고 고유하지만 소중하고 공감 가능한지 전해드리고자 노력합니다.', null, 'https://www.instagram.com/nicetoneet/', 310),
  (311, 'B400', 'B435', '코스모 프레스', 'kosmo press', null, null, true, array['예술']::text[], '[코스모 프레스]는 그림과 만화를 그리는 작가 ‘우주’가 설립한 1인 출판사입니다. 기억을 잃은 채 폐허가 된 가상 세계를 탐험하는 캐릭터 ‘누리’의 여정을 시리즈로 펴내며, 이를 다양한 판형과 실험적인 제작 방식의 도서로 구현합니다. nuri journey를 통해 문명이 멈춘 자리에서 누리가 채집한 사물, 건물, 그리고 인간의 흔적들을 집요하게 기록합니다. 누리의 시선을 빌려 익숙한 것들을 낯설게 바라보고, 잊혀가는 것들의 가치를 다시금 조명하여 사색적인 즐거움을 전달하고자 합니다.', null, 'https://www.instagram.com/nuri_wj/', 311),
  (312, 'B400', 'B436', '아뜰리에아쉬', 'AtelierH', null, null, true, array['철학','예술','아동']::text[], '일상에서 잊혀 가지만 우리가 결코 놓쳐서는 안 될 가치 있는 것들을 발견하여 기록하는 논픽션 그림책 출판사, 아뜰리에 아쉬입니다. 빠르게 변하는 세상 속에서 사라져 가는 것들을 발굴하고, 이를 ''인포그래픽''이라는 친절하고 직관적인 언어로 담아내는 데 집중하고 있습니다.', 'https://www.hyelilee.com/BooksItems', null, 312),
  (313, 'B400', 'B437', '라우트 프레스', 'Route Press', null, null, true, array['예술','문학']::text[], '라우트 프레스는 서울을 기반으로 한 출판사입니다. 아직 소개되지 못했거나 잘 알려지지 않았던, 그러나 분명 존재하는 것들에 대해 관심을 두고 있습니다. 우리가 잘 알지 못했던 한국 근대 여성 작가들의 작품을 책으로 엮은 『한국근대여성문학전집』을 2020년부터 매년 한 권씩 출간해 왔고, 글과 책, 글자와 종이로 된 것에 관심을 두며 책을 만듭니다. 라우트 프레스는 주어진 길을 의심 없이 따르기보다는 새로운 길이 존재할 수 있음을 믿으며, 책이라는 형식에 대한 탐구와 출판 활동을 통해 사회 안에서 자신만의 길을 개척해 나가는 움직임을 전하고 싶습니다.', 'http://route-press.com', 'https://instagram.com/sca_laska/', 313),
  (314, 'B400', 'B438', '오큐파이 더 시티', 'Occupy the City', null, null, true, array['예술']::text[], '오큐파이 더 시티는 서울에 위치한 소규모 출판사입니다. 2014년 타이포그래피에 관한 비정기간행물 «Typozimmer» 발행을 시작으로 출판 활동을 지속하고 있습니다. 그래픽 디자인과 타이포그래피 관련 서적을 주로 발행하고 있습니다. 현재 10호까지 발행한 «Typozimmer»의 목표는 현대 타이포그래피와 그래픽 디자인에 대한 관심을 불규칙하고 예측할 수 없는 흐름으로 제시하는 것입니다.', 'https://smartstore.naver.com/aoct', null, 314),
  (315, 'B400', 'B439', '길고도 짧은 이야기', 'longshortstory', null, null, true, array['예술']::text[], '밀려오고 이내 쓸려가는 길고도 짧은 순간들을 수집합니다.'' 길고도 짧은 이야기는 반복과 변주를 통해 일상 속 패턴과 시각적 내러티브를 탐구하는 서울 기반의 독립출판사입니다. 매일의 움직임, 공간의 인상, 구조와 실루엣처럼 쉽게 지나칠 수 있는 감각들을 아카이빙 하고, 각각의 독립된 장면들을 느슨한 서사 구조로 재조합한 책과 인쇄물을 제작해 왔습니다. 『수상한 언덕 위의 춤』을 시작으로 아트북과 패턴 북 등 다양한 형식의 출판물을 선보이며, 국내외 아트북 페어와 전시를 통해 독자와 직접 만나고 있습니다. 출판을 하나의 실험적 매체로 삼아, 장면과 리듬, 책의 물성 자체에 대한 연구를 지속하며, 일상과 공간에서 포착한 감각을 출발점으로 책이라는 형식을 통해 사유와 경험이 확장되는 방식을 탐구하고자 합니다.', 'https://cargocollective.com/longshortstory', 'https://www.instagram.com/longshortstory/', 315),
  (316, 'B400', 'B440', '무주산골영화제', 'MJFF', null, null, true, array['예술']::text[], '2013년부터 시작해 2026년 14회를 맞이한 무주산골영화제는 영화와 자연이 만나는 곳, 큐레이션이 곧 경험이 되는 영화제로서, 매년 6월 초 전북특별자치도 무주군에서 열립니다. 무주의 푸른 자연 속에서 자유롭게 즐길 수 있는 무주산골영화제는 도시의 밀도와 소음에서 벗어난 특별한 영화적 만남을 제안합니다. 매년 약 20개국 80~90편의 영화를 상영하며, 한국 독립영화를 중심으로 엄선된 전 세계 독립예술영화를 소개합니다. 또한 동시대 영화와 관련한 전문 시리즈 도서 출판도 꾸준히 이어오고 있습니다. 연간 약 3만 명 이상의 관객이 방문하는 이 영화제는 한국에서 가장 중요한 영화제 중 하나이자, 관객과 영화인 모두가 가장 가고 싶어 하는 영화제로 알려져 있습니다.', 'http://www.mjff.or.kr', null, 316),
  (317, 'B400', 'B441', '미스테리어스플랜트', 'mysterious plant', null, null, true, array['순수과학','문학']::text[], '미스테리어스플랜트는 식물생태학자와 디자이너 2인이 식물의 이야기를 책과 소품으로 전하는 팀입니다. 가까운 식물들의 또 다른 모습을 발견하고 함께할 수 있는 방법을 제안합니다. 매일 걷는 길가와 집 뒷산에서 보는 평범한 식물, 저절로 나고 자라는 우리 주변 식물에 관심이 많습니다. 알면 알수록 사랑할 수밖에 없는 이 존재는 항상 우리 곁에 있으며, 조금만 고개를 돌리고 들여다본다면 수수한 자연이 주는 감동과 즐거움을 느낄 수 있다는 생각을 담습니다.', null, 'https://www.instagram.com/mysteriousplant.kr/', 317),
  (318, 'B400', 'B442', '소화당', 'SoHwaDang', null, null, true, array['예술']::text[], '小畵堂 - My Small Studio 그리는 사람이 그의 그림과 생각을 모아 책을 펴냈습니다. 책상 위 작은 미술관으로 여러분을 초대합니다. 작은 그림이 있는 집. -소화당 원희 : 그리는 사람 1983년 서울에서 나고 자랐습니다. 어려서는 만화 그리기를 좋아했고 대학에서 동양화를 전공하였습니다. 아름다운 사람의 몸을 직접 보고 그 자리에서 일필로 그립니다. 이런저런 느낀 것을 곱씹다 짧은 글을 쓰고, 그림 한 편에 찍을 인장을 직접 새깁니다. 그림과 생각을 나누는 방법을 고민해 본인이 지은 화실의 이름을 가져와 출판사 ‘소화당’을 만들었습니다. 작은 그림이 있는 집 혹은, 나의 작은 화실이라는 뜻입니다. ‘소화당’을 통해 보고 그리고 새겨낸 많은 이야기들을 함께 나누고 싶습니다.', null, 'https://www.instagram.com/sohwadang.art/', 318),
  (319, 'B400', 'B443', '김주영', 'Joo Young Kim', null, null, true, array['예술']::text[], '독일에서 그림을 그리고 있는 김주영입니다.독일에서 그림을 그립니다. 2019년 『Welcome to My Life』, 『 번역이 안 되는 독일어 단어들』을 독립출판하고 그 해 여러 독립출판 아트북 페어에 참가하며 활동을 시작했습니다. 그 후 독립서점이자 출판사인 유어마인드에서 출판된 『이렇게 저렇게 명이나 물 페스토 김주영 팝업북』, 코우너스에서 출판된 『체조』, 라트비아 독립 만화 출판사인 Kush komikss 에서 출판된 만화 『World Ceramic Fair』등의 책들을 만들었습니다. 2021년 한국 여성 만화작가들과 함께 한 성인 학습만화 프로젝트 『 성인 학습 만화 - 눈물 참는 법』, 2022년 그림책 『Six』, 2023년 『독일 산책 가이드』 등을 독립출판 하였습니다.', null, 'https://www.instagram.com/joo_bilder/', 319),
  (320, 'B400', 'B444', '삐약삐약북스', 'PPIYACKPPIYACK BOOKS', null, null, true, array['기타(만화)']::text[], '한국의 전북 군산을 기반으로 활동하고 있는 2인 만화출판사 삐약삐약북스는 2019년 겨울, 처음으로 발간한 을 들고 전국의 독립서점을 방방곡곡 찾아다녔던 일을 시작으로 2020년부터 한국지역만화 프로젝트 를 최종 99권 제작을 목표로 매년 9권씩 발표하고 있습니다. 2023년 한국 음악씬을 아카이빙하는 만화제작 프로젝트 을 통해 한국 음악가를 만화로 조명했으며, 2024년 학교 안팎의 청소년을 위한 만화단편집 프로젝트, 한국 인디밴드 브로콜리너마저 4집 기념 만화책 를 발간하였습니다.', null, 'https://www.instagram.com/ppiyackppiyackbooks/', 320),
  (321, 'B400', 'B445', '카인드오브썸머', 'KIND OF SUMMER', null, null, true, array['예술']::text[], '자연이 들려주는 이야기를 기록하는 출판사, 카인드오브썸머입니다. 2017년부터 자연 초상 작업을 이어오며 식물이 지닌 고유한 존재성과 그 순간의 이야기를 사진으로 채집하고 기록해왔습니다. 그렇게 축적된 기록은 대표작 ‘FLORESTA’, ''자연초상''을 비롯해 자연과 사람이 마주하는 순간을 담은 다양한 형태의 아트북으로 이어지고 있습니다. 단순한 시각적 기록을 넘어 자연이 전하는 위로와 공감을 출판을 통해 나누고자 하며, 수제본 독립출판물부터 일상 속에서 자연을 떠올릴 수 있는 인쇄물까지 자연의 이야기가 독자의 하루에 머무르길 바랍니다.', 'https://kindofsummer.com/', 'https://www.instagram.com/kindofsummer_official/', 321),
  (322, 'B400', 'B446', '마블로켓', 'MARBLEROCKET', null, null, true, array['예술','역사','기타(매거진)']::text[], '마블로켓매거진은 도시를 새롭게 볼 수 있는 관점을 제안하는 도시 탐사 시리즈입니다. 각 도시마다 새로운 프레임을 제시하여 도시를 대한 이해와 흥미의 폭을 확대하고자 합니다.', 'https://marblerocket.com/', 'https://www.instagram.com/marble_rocket/', 322),
  (323, 'B400', 'B447', '블루토마토즈', 'bluetomatoes', null, null, true, array['예술']::text[], '는 한 손에 쥐어지는 따뜻한 책을 만듭니다. 오일파스텔로 평범한 일상의 풍경을 특별한 시선으로 담아내는 일러스트레이터 순심 작가가 직접 기획하고 제작하는 1인 독립 출판사로, 색감과 촉감이 살아 있는 감각적인 책과 인쇄물을 지향합니다. 토마토는 보통 빨간색이지만, 우리는 그 안에 숨어 있는 파란색 토마토들의 작고 조용한 마음에 귀 기울입니다. 세상의 기준에서 비껴난 시무룩한 마음을 돌보고, 당당해진 파란 토마토들이 각자의 색으로 존재하는 세상을 꿈꿉니다. 블루토마토즈는 우리의 하루를 조금 더 사랑하게 만드는 작업으로, 파란 토마토들의 손 위에 알록달록한 색의 즐거움을 전하고자 합니다.', 'https://soonsim.co.kr/bluetomatoes', null, 323),
  (324, 'B400', 'B448', '노말에이', 'NOrmal A', null, null, true, array['예술','문학']::text[], '노말에이는 디자인 스튜디오 131watt가 운영하는 서점이자 출판사로, 서울 을지로에서 책과 문구를 소개하며 출판을 병행하고 있습니다. 서점에서는 독립출판물과 서적, 문구를 큐레이션하고, 출판에서는 시각적 완성도와 물성을 중시한 자체 기획 도서를 선보입니다.', 'https://normala.kr/131watt', 'https://www.instagram.com/normala.kr/', 324),
  (325, 'B400', 'B449', '연필과머그', 'Pencil and Mug', null, null, true, array['사회과학','문학','기타(취미/실용)']::text[], '연필과머그는 사람들의 영감을 깨우고 일상에 즐거움을 더하는 콘텐츠를 만드는 출판사입니다. 커피와 이야기를 좋아하는 두 명의 편집자가 함께 활동하고 있으며, 독자들과 마주 앉아 작고 소소한 이야기도 즐겁게 나눌 수 있는 ‘커피 친구’ 같은 출판사를 지향합니다. 그동안 커피를 매개로 미식과 문화, 그리고 사람의 삶을 기록하며 창작의 즐거움을 전하는 책 4권을 출간했고, 출판을 기반으로 커피 문화를 확장하는 다양한 프로젝트도 이어왔습니다. 앞으로도 연필과머그는 커피, 인물, 공간이라는 세 가지 주제 아래 창작자 네트워크를 넓혀가며, 각자의 크리에이티브가 독자와 만나는 여정을 함께 만들어가고자 합니다.', null, 'https://www.instagram.com/pencilandmug/', 325),
  (326, 'B400', 'B450', '까막북', 'KKAMAKBOOK', null, null, true, array['예술','기타(만화)']::text[], '안녕하세요. 까막북은 21년도 중철 단편 만화를 사랑하는 작가 유진과 도원이 함께 만든 팀 프로젝트에서 출발하여 작년부터 출판사 [까막북]으로 새로운 단추를 달았습니다. 까막북의 대표 시리즈는 로 제목을 먼저 정하고 이야기를 만드는 시리즈입니다. 도통 잘 붙지 않는 단어들을 조합하여 제목을 정합니다. 제목은 곧 이야기의 시작이 되어 만드는 작가도 읽는 독자에게도 흥미를 유발합니다. 초단편 컬러 중철 만화로 그림책과 그래픽 노블의 영역에서 가볍게 읽을 수 있는 시리즈를 만들고 있습니다. 시리즈를 메인으로 출판하여 현재 『키우던 잉어가 풍선이 되었다』, 『오늘 선인장이 내 신발을 신고 도망갔다』 를 포함하여 11종의 책이 쌓였습니다.', null, 'https://www.instagram.com/kkamakbook/', 326),
  (327, 'B400', 'B451', '에트르', 'ETRE', null, null, true, array['철학','예술','문학']::text[], '에트르는 “곁에 있어 든든한 존재가 되는 책”을 모토로 삼아 2022년에 문을 연 1인 출판사입니다. 에트르는 프랑스어로 “존재”를 뜻합니다. 읽는 존재로서의 독자, 텍스트와 디자인 그리고 종이라는 물성으로 존재하는 책을 생각하며 지은 이름입니다. 리디아 데이비스 《형식과 영향력》 《못해 그리고 안 할 거야》/ 제나 히츠 《찬란하고 무용한 공부》 / 제인 앨리슨 《구불구불 빙빙 팡 터지며 전진하는 서사》 / 비비언 고닉 《멀리 오래 보기》 / 이주혜 《눈물을 심어본 적 있는 당신에게》 / 박보나 《예술이 내 것이 되는 순간》 등 작가의 통찰력이 빛나는 문학과 인문, 예술 책을 내고 있습니다. 현재 총 10권 출간했습니다.', null, 'https://instagram.com/etrebooks/', 327),
  (328, 'B400', 'B452', '책덕', 'Bookduck', null, null, true, array['예술','문학']::text[], '책덕 출판사는 자유일꾼 김민희가 운영하는 1인출판사로, ''이상하고 멋진 것을 찾아서'' 책으로 만드는 출판사입니다. 여성 코미디언의 에세이 시리즈 코믹릴리프를 펴냈으며 조울증 청년의 8년의 감정이 담긴 일기장 를 펴냈습니다. 시대가 나를 변화시키기 전에 내가 먼저 변화를 시도하는 자유일꾼에게 필요한 책을 계속해서 펴나갈 예정입니다.', null, 'https://www.instagram.com/bookduck.kr/', 328),
  (329, 'B400', 'B453', '디 오브젝트', 'the object', null, null, true, array['예술']::text[], '‘디오브젝트’는 일상의 사물에서 많은 영감을 얻는 디자인 스튜디오 겸 출판사입니다. 실크스크린과 핸드 바인딩 등 수작업으로 제작하는 아트북과, 국내외 아티스트와 협업하는 다양한 형식의 일러스트북, 사진 아카이브 연구소와 함께 만드는 『다쉬브』 시리즈를 기획 및 제작해오고 있습니다. 조용하고 오래된 것에 관심이 많고, 책의 물성에 자주 감탄합니다. 소재와 방법에 대한 고민으로 많은 시간을 보내고 손으로 하는 작업에서 즐거움을 느낍니다. 0.1과 함께 오브제, 전통, 수집 등의 키워드를 다양한 형태의 책으로 표현하는 ‘Add to cart’ 프로젝트를 진행중입니다.', 'http://the-object.co.kr/', 'https://instagram.com/the__object/', 329),
  (330, 'B400', 'B454', 'TEMPORARY BOOKSHOP | C시지G', 'TEMPORARY BOOKSHOP | CsijiG', null, null, true, array['예술']::text[], 'TEMPORARY BOOKSHOP은 북페어라는 조건 속에서 책의 배치와 읽기 방식을 실험하는 출판사 C시지G의 운영 포맷입니다. 미술 작업의 과정과 결과를 책이라는 매체로 다루며 구조물 설치와 출판물을 통해 책을 하나의 경험적·조형적 인터페이스로 구성합니다.', null, 'https://www.instagram.com/c_siji_g/', 330),
  (331, 'B400', 'B455', '파도', 'SEEYOURSEA', null, null, true, array['문학']::text[], '안녕하십니까, 문학출판사 입니다. 우리는 하나의 세상에서 각자의 인생을 살아갑니다. 서로의 세계를 공유하고 이해할 때, 세상은 더욱 다채로워집니다. 파도는 세계와 세계를 잇는 매개체가 되기 위해 앞장서고 노력합니다. 파도는 문학에 대한 진입장벽을 낮추고 누구나 즐길 수 있는 문학을 만듭니다. 크게 두 가지로, 모두의 의미를 엮어 책으로 만드는 과 세상의 모든 사유를 문학으로 남기는 가 있으며, 꾸준한 시리즈 출간으로 독자들의 관심과 사랑을 받아 성장하고 있습니다. ［파도와 파도가 모여 바다가 되는 것처럼, 당신과 내가 만나 우리가 되는 것처럼.］ 파도의 슬로건처럼 소외되거나 상처 받는 이 없이 모든 생명이 존중 받는 세상이 되기 위한 책을 만듭니다.', 'https://seeyoursea.imweb.me/book', null, 331),
  (332, 'B400', 'B456', '선과 결', 'LineGrain', null, null, true, array['예술']::text[], '선과 선이 모여서 만들어내는 작업을 합니다. 선이 모인 그림을 그리고 그 그림으로 선이 중심이 되는 그림같은 책을 만들어가는 입니다.', 'http://linegrain.kr', null, 332),
  (333, 'B400', 'B457', '탱크 프레스', 'TANK Press', null, null, true, array['예술']::text[], 'Tank Press는 2021년부터 사진을 비롯한 시각언어로 작업하며, 책을 만들어 선보이던 이들이 2023년, 출판을 목표로 만든 출판사이자 브랜드다. 오늘날의 이미지 속성에 대해 고찰하며, 데이터와 물성을 가진 개체 간에 상호작용과 이미지를 보여주는 방식에 대해 이야기한다.', null, 'https://www.instagram.com/tank.press/', 333),
  (334, 'B400', 'B458', '바이블랭크', 'by_[blank]', null, null, true, array['예술']::text[], '바이블랭크는 일상에서 쉽게 마주할 수 있는 공간 속에 담긴 다양한 이야기에 귀 기울입니다. 작은 이야기는 새로운 이야기의 발판이 되기도 하고, 더 큰 이야기를 만들어내기도 합니다. 우리의 작은 기획이 다른 사람에게 영감을 주길 바랍니다.', 'https://www.notion.so/byblank/published-by_-330ce8c92a0846b38833b73e6299be5f?source=copy_link', 'https://www.instagram.com/notionhq/', 334),
  (335, 'B400', 'B459', '', 'te editions', '미국', 'USA', true, '{}'::text[], null, null, null, 335),
